class InspireAsyncClient(AsyncRuntime):

    """Share one client across tasks on the same process and event loop.

    Account/configuration are pinned on first use, not construction.
    concurrency is a deprecated positive-integer no-op; use an application
    semaphore to limit requests. Local I/O uses a separate four-worker pool.
    Close with async with or await close(); cancellation does not stop
    remote workloads or forcibly interrupt running local offloads.
    """

    accounts = Accounts


    def __init__(
        self,
        account: str | None = None,
        *,

        username: str | None = None,

        password: str | None = None,

        base_url: str | None = None,

        proxy: str | None = None,

        allow_browser: bool = False,

        timeout: float = 30,

        operation_timeout: float = 120,

        catalog_ttl: float = 60,

        catalog_disk_cache: bool = False,

        concurrency: int | None = None,
    ) -> None:

        super().__init__({
            'account': account,
            'username': username,
            'password': password,
            'base_url': base_url,
            'proxy': proxy,
            'allow_browser': allow_browser,
            'timeout': timeout,
            'operation_timeout': operation_timeout,
            'catalog_ttl': catalog_ttl,
            'catalog_disk_cache': catalog_disk_cache,
        }, concurrency)

        self.cache = AsyncCatalogCache(self)

        self.workspaces = AsyncWorkspaces(self)

        self.projects = AsyncProjects(self)

        self.compute_groups = AsyncComputeGroups(self)

        self.images = AsyncImages(self)

        self.jobs = AsyncJobs(self)

        self.hpc = AsyncHPC(self)

        self.ray = AsyncRay(self)

        self.servings = AsyncServings(self)

        self.tensorboards = AsyncTensorboards(self)

        self.notebooks = AsyncNotebooks(self)

        self.account_info = AsyncAccountInformation(self)

        self.api_keys = AsyncAPIKeys(self)

        self.datasets = AsyncDatasets(self)

        self.models = AsyncModels(self)

        self.resources = AsyncResources(self)


    @classmethod
    def from_credentials(
        cls, username: str, password: str, *, base_url: str | None = None,
        proxy: str | None = None, account: str | None = None, **client_kwargs: Any,
    ) -> InspireAsyncClient:
        return cls(account, username=username, password=password, base_url=base_url,
                   proxy=proxy, **client_kwargs)

    @property
    def account(self) -> str:
        if self._account is None:
            raise ConfigurationError("account is available after the first operation or entering async with client.")
        return self._account

    @property
    def base_url(self) -> str:
        if self._base_url is None:
            raise ConfigurationError("base_url is available after the first operation or entering async with client.")
        return self._base_url

    async def login(self, *, force: bool = False) -> AccountInfo:
        return await self._call("", "login", force=force)

    async def init(self, *, force: bool = False) -> InitResult:
        return await self._call("", "init", force=force)

    async def __aenter__(self) -> InspireAsyncClient:
        await self._start()
        return self

    async def __aexit__(self, *args: Any) -> None:
        await self.close()
